    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None
        self.height = 1

def get_height(node):
    return node.height if node else 0

def update_height(node):
    node.height = 1 + max(get_height(node.left), get_height(node.right))

def get_balance(node):
    return get_height(node.left) - get_height(node.right) if node else 0

def rotate_right(y):
    x = y.left
    T2 = x.right
    x.right = y
    y.left = T2
    update_height(y)
    update_height(x)
    return x

def rotate_left(x):
    y = x.right
    T2 = y.left
    y.left = x
    x.right = T2
    update_height(x)
    update_height(y)
    return y

def insert(root, key):
    # 基础插入（无旋转），供学生在此基础上实现完整 AVL 插入
    if root is None:
        return AVLNode(key)
    if key < root.key:
        root.left = insert(root.left, key)
    elif key > root.key:
        root.right = insert(root.right, key)
    else:
        return root
    update_height(root)
    # TODO: 检查平衡因子并执行旋转
    return root

def inorder(root, res):
    if root:
        inorder(root.left, res)
        res.append(root.key)
        inorder(root.right, res)

def is_balanced(root):
    if not root:
        return True
    if abs(get_balance(root)) > 1:
        return False
    return is_balanced(root.left) and is_balanced(root.right)

# 测试用例：简单序列，仅验证基本插入和遍历
keys = [10, 20, 30]
root = None
for k in keys:
    root = insert(root, k)

result = []
inorder(root, result)
print("中序遍历:", result)
print("是否平衡:", is_balanced(root))
print("树高:", get_height(root))
print("提示：当前 insert 仅实现递归插入，未包含旋转逻辑。请补充平衡检查与四种旋转。")"}, "env": {"kind": "custom", "output": "console", "resultLabel": "运行结果", "pythonPreamble": "# 提供 AVL 节点类、辅助函数和测试数据，学生需完成 insert 函数中的旋转逻辑"}, "hint": "修改代码后点击 Run", "consoleHint": "运行日志与测试结果显示在这里", "id": "s10b0"}], "layout": {"kind": "full"}}, "referenceMaterial": "[none provided]"}

